namespace ghidra.util.classfinder;





using ghidra.util;
using ghidra.util.exception;
using ghidra.util.task;

class ClassPackage : ClassLocation {

	private static readonly FileFilter CLASS_FILTER =
		pathname => pathname.getName().endsWith(CLASS_EXT);

	private Set<ClassPackage> children = new();
	private ClassDir classDir;
	private File packageDir;
	private string packageName;
	private Set<ClassFileInfo> classes = new();

	ClassPackage(ClassDir classDir, string packageName, TaskMonitor monitor)
    {
		monitor.checkCancelled();

		this.classDir = classDir;

		File rootDir = classDir.getDir();
		this.packageName = packageName;
		this.packageDir = new File(rootDir, packageName.replace('.', File.separatorChar));
		scanClasses(rootDir);
		scanSubPackages(monitor);
	}

	private void scanClasses(File rootDir) {

		string path = rootDir.getAbsolutePath();
		Set<string> allClassNames = getAllClassNames();
		foreach (string className in allClassNames) {
			string epName = ClassSearcher.getExtensionPointSuffix(className);
			if (epName != null) {
				string module = classDir.getModulePath();
				classes.add(new ClassFileInfo(path, className, epName, module));
			}
		}
	}

	private void scanSubPackages(TaskMonitor monitor)
    {

		File[] subdirs = packageDir.listFiles();
		if (subdirs == null) {
			Msg.debug(this, "Directory does not exist: " + packageDir);
			return;
		}

		foreach (File subdir in subdirs) {
			monitor.checkCancelled();
			if (!subdir.isDirectory()) {
				continue;
			}

			string pkg = subdir.getName();
			if (pkg.contains(".")) {
				// java can't handle dir names with '.'-- it conflicts with the package structure
				continue;
			}

			if (packageName.length() > 0) {
				pkg = packageName + "." + pkg;
			}

			monitor.setMessage("Scanning package: " + pkg);
			children.add(new ClassPackage(classDir, pkg, monitor));
		}
	}

	/* @Override */
	public void getClasses(List<ClassFileInfo> list, TaskMonitor monitor)
    {

		list.addAll(classes);

		foreach (ClassPackage subPkg in children) {
			monitor.checkCancelled();
			subPkg.getClasses(list, monitor);
		}
	}

	private Set<string> getAllClassNames() {

		File[] files = packageDir.listFiles(CLASS_FILTER);
		if (files == null) {
			return Collections.emptySet();
		}

		Set<string> results = new(files.length);
		foreach (File file in files) {
			string name = file.getName();
			name = name.substring(0, name.length() - 6);
			if (packageName.length() > 0) {
				name = packageName + "." + name;
			}
			results.add(name);
		}
		return results;
	}

	/* @Override */
	public string toString() {
		return packageDir.toString();
	}
}
